perfpath=U/'Saved/PackageTests/PerformanceV25_hospital37_after/Saved/Prototype/hospital_perf_hospital37_after.json';perf=read(perfpath);assert perf['success'] and perf['executable_sha256']==h and perf['screen_percentage']==100 and len(perf['views'])==8
